solution:
function rob(houses) {
  let bestTwoBack = 0;                     // best total up to house i - 2
  let bestOneBack = 0;                     // best total up to house i - 1
  for (const money of houses) {
    const take = bestTwoBack + money;      // rob this house: previous one must be skipped
    const skip = bestOneBack;              // skip this house: keep the best so far
    const best = Math.max(take, skip);
    bestTwoBack = bestOneBack;
    bestOneBack = best;
  }
  return bestOneBack;
}

